{
  "openapi": "3.1.0",
  "info": {
    "title": "Weather API",
    "version": "2"
  },
  "paths": {
    "/forecast/{city}": {
      "get": {
        "summary": "Forecast for a city",
        "description": "Seven-day forecast.",
        "parameters": [
          {
            "name": "city",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "units",
            "in": "query",
            "schema": {
              "type": "string",
              "enum": [
                "metric",
                "imperial"
              ],
              "default": "metric"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Forecast",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object"
                }
              }
            }
          }
        }
      }
    },
    "/alerts": {
      "get": {
        "summary": "Active weather alerts",
        "responses": {
          "200": {
            "description": "Alerts"
          }
        }
      }
    }
  }
}
